"""Typed builders. Generated by `python -m ekbatan.codegen n2pkg.generic_model`.

Regenerate this when a model gains or loses a field. A stale builder is a type error
rather than a wrong answer: build() calls the real constructor, which will refuse.
"""

from __future__ import annotations

from ekbatan.domain import ModelBuilder
from typing import Self, TYPE_CHECKING

if TYPE_CHECKING:
    from ekbatan.domain import GenericState  # noqa: F401
    from ekbatan.ids import Id  # noqa: F401
    from .generic_model import Box  # noqa: F401

class BoxBuilder(ModelBuilder["Box", "Id[Box]", "GenericState"]):
    """Builds a Box, with the field types a checker can see.

    id, state, version and the timestamps come from ModelBuilder, typed by the
    parameters above, so only the fields Box added are declared here.
    """

    builds_ref = "n2pkg.generic_model:Box"

    def content(self, value: Any) -> Self:
        return self.set(content=value)

def box(source: Box | None = None) -> BoxBuilder:
    """A fresh BoxBuilder, optionally pre-loaded from an existing Box."""
    made = BoxBuilder()
    return made.copy_base(source) if source is not None else made
